//! Executable vote-call contexts and distinct reply collection.
//! RPC transport provenance and durable self-vote composition remain caller obligations.
use super::state::{VoteRequest, VoteReply};
use vstd::prelude::*;
verus! {
pub struct VoteCall { request: VoteRequest, peer: usize }
pub struct Tally {
    request: VoteRequest,
    members: usize,
    voters: Vec<usize>,
    replies: Ghost<Seq<(usize, Option<VoteReply>)>>,
}
pub struct TallyView {
    pub request: VoteRequest,
    pub members: usize,
    pub voters: Seq<usize>,
    pub replies: Seq<(usize, Option<VoteReply>)>,
}
pub open spec fn granted(v: TallyView, peer: usize, reply: Option<VoteReply>) -> bool {
    peer < v.members && reply.is_some() && reply.unwrap().term == v.request.term && reply.unwrap().granted
}
pub open spec fn valid(v: TallyView) -> bool {
    v.members > 0 && v.request.candidate < v.members
    && v.voters.no_duplicates()
    && forall|i: int| 0 <= i < v.voters.len() ==> #[trigger] v.voters[i] < v.members
        && exists|j: int| 0 <= j < v.replies.len() && v.replies[j].0 == v.voters[i]
            && granted(v, v.voters[i], v.replies[j].1)
}
pub open spec fn record_step(s: TallyView, peer: usize, reply: Option<VoteReply>, t: TallyView) -> bool {
    t.request == s.request && t.members == s.members
    && t.replies == s.replies.push((peer, reply))
    && t.voters == if granted(s, peer, reply) && !s.voters.contains(peer) { s.voters.push(peer) } else { s.voters }
}
impl VoteCall {
    pub closed spec fn request(&self) -> VoteRequest { self.request }
    pub closed spec fn peer(&self) -> usize { self.peer }
    pub fn args(&self) -> (q: VoteRequest) ensures q == self.request(), { self.request }
    pub fn destination(&self) -> (p: usize) ensures p == self.peer(), { self.peer }
}
impl Tally {
    pub closed spec fn view(&self) -> TallyView {
        TallyView { request: self.request, members: self.members, voters: self.voters@, replies: self.replies@ }
    }
    pub closed spec fn invariant(&self) -> bool { valid(self.view()) }
    pub fn new(request: VoteRequest, members: usize) -> (r: Option<Self>)
        ensures r.is_some() == (members > 0 && request.candidate < members),
            r.is_some() ==> r.unwrap().invariant() && r.unwrap().view().request == request
                && r.unwrap().view().members == members && r.unwrap().view().voters.len() == 0
                && r.unwrap().view().replies.len() == 0,
    {
        if members == 0 || request.candidate >= members { return None; }
        Some(Self { request, members, voters: Vec::new(), replies: Ghost(Seq::empty()) })
    }
    pub fn outbound(&self, peer: usize) -> (r: Option<VoteCall>)
        ensures r.is_some() == (peer < self.view().members && peer != self.view().request.candidate),
            r.is_some() ==> r.unwrap().request() == self.view().request && r.unwrap().peer() == peer,
    {
        if peer >= self.members || peer == self.request.candidate { return None; }
        Some(VoteCall { request: self.request, peer })
    }
    fn contains(&self, peer: usize) -> (r: bool)
        ensures r == self.view().voters.contains(peer),
    {
        let mut i = 0;
        while i < self.voters.len()
            invariant i <= self.voters.len(),
                forall|j: int| 0 <= j < i ==> self.voters[j] != peer,
            decreases self.voters.len() - i,
        {
            if self.voters[i] == peer { return true; }
            i += 1;
        }
        false
    }
    pub proof fn evidence(&self)
        requires self.invariant(),
        ensures valid(self.view()),
    {}
    pub fn record(&mut self, peer: usize, reply: Option<VoteReply>)
        requires old(self).invariant(),
        ensures self.invariant(), record_step(old(self).view(), peer, reply, self.view()),
    {
        let ghost before = self.view();
        self.replies = Ghost(self.replies@.push((peer, reply)));
        let accepted = match reply { Some(r) => peer < self.members && r.term == self.request.term && r.granted, None => false };
        if accepted && !self.contains(peer) {
            self.voters.push(peer);
            assert(self.voters@.no_duplicates());
        }
        let ghost after = self.view();
        assert forall|i: int| 0 <= i < after.voters.len() implies #[trigger] after.voters[i] < after.members
            && exists|j: int| 0 <= j < after.replies.len() && after.replies[j].0 == after.voters[i]
                && granted(after, after.voters[i], after.replies[j].1) by {
            if i < before.voters.len() {
                assert(before.voters[i] < before.members);
                let j = choose|j: int| 0 <= j < before.replies.len() && before.replies[j].0 == before.voters[i]
                    && granted(before, before.voters[i], before.replies[j].1);
                assert(after.replies[j] == before.replies[j]);
                assert(granted(after, after.voters[i], after.replies[j].1));
            } else {
                let j = before.replies.len() as int;
                assert(after.replies[j] == (peer, reply));
                assert(granted(after, after.voters[i], after.replies[j].1));
            }
        }
    }
    pub fn complete_call(&mut self, call: VoteCall, reply: Option<VoteReply>)
        requires old(self).invariant(),
        ensures self.invariant(),
            call.request() == old(self).view().request ==>
                record_step(old(self).view(), call.peer(), reply, self.view()),
            call.request() != old(self).view().request ==> self.view() == old(self).view(),
    {
        let q = call.request;
        if q.term != self.request.term || q.candidate != self.request.candidate
            || q.last_index != self.request.last_index || q.last_term != self.request.last_term { return; }
        self.record(call.peer, reply);
    }
    pub fn has_quorum(&self) -> (r: bool)
        requires self.invariant(),
        ensures r == (self.view().voters.len() > self.view().members / 2),
    { self.voters.len() > self.members / 2 }
}
}
//! Verified request/storage/reply phases used by the asynchronous Raft host.
use super::state::{self, State, VoteRequest, VoteReply};
use vstd::prelude::*;

verus! {
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[cfg_attr(not(verus_keep_ghost), derive(serde::Serialize, serde::Deserialize))]
pub struct VoteImage {
    pub version: u64,
    pub term: u64,
    pub voted_for: Option<usize>,
    pub me: usize,
    pub members: usize,
}

// Only begin_vote constructs this operation. The host borrows its image while
// writing, then returns the owned operation after successful I/O completion.
pub struct WriteVote { id: u64, image: VoteImage }

#[derive(Clone, Copy)]
struct PendingVote {
    id: u64,
    image: VoteImage,
    request: VoteRequest,
    reply: VoteReply,
    before: Ghost<State>,
}

pub struct Machine {
    state: State,
    serial: u64,
    pending: Option<PendingVote>,
}

pub open spec fn image(s: State) -> VoteImage {
    VoteImage { version: 1, term: s.term, voted_for: s.voted_for, me: s.me, members: s.members }
}

// Observable local operation state, including the pending request and exact reply.
pub struct OperationView {
    pub state: State,
    pub serial: u64,
    pub pending: Option<(u64, VoteImage, VoteRequest, VoteReply, State)>,
}

pub open spec fn view_invariant(v: OperationView) -> bool {
    state::well_formed(v.state) && v.state.last_index == 0 && v.state.last_term == 0
    && match v.pending {
        None => true,
        Some(p) => p.0 == v.serial && p.1 == image(v.state)
            && state::well_formed(p.4) && state::vote_step(p.4, p.2, v.state, p.3),
    }
}

pub open spec fn initial_view(v: OperationView, me: usize, members: usize) -> bool {
    state::initial(v.state, me, members) && v.serial == 0 && v.pending.is_none()
}

pub open spec fn begin_step(s: OperationView, q: VoteRequest, t: OperationView,
    output: Option<(u64, VoteImage)>) -> bool {
    if s.pending.is_some() || s.serial == u64::MAX {
        t == s && output.is_none()
    } else {
        t.serial == s.serial + 1 && t.pending.is_some()
        && t.pending.unwrap().0 == t.serial && t.pending.unwrap().1 == image(t.state)
        && t.pending.unwrap().2 == q && t.pending.unwrap().4 == s.state
        && state::vote_step(s.state, q, t.state, t.pending.unwrap().3)
        && output == Some((t.serial, image(t.state)))
    }
}

pub open spec fn complete_step(s: OperationView, id: u64, saved: VoteImage,
    t: OperationView, reply: Option<VoteReply>) -> bool {
    if s.pending.is_some() && s.pending.unwrap().0 == id && s.pending.unwrap().1 == saved {
        t.state == s.state && t.serial == s.serial && t.pending.is_none()
        && reply == Some(s.pending.unwrap().3)
    } else { t == s && reply.is_none() }
}

pub open spec fn campaign_step(s: OperationView, term: u64, t: OperationView, ok: bool) -> bool {
    ok == (s.pending.is_none() && s.state.term == term && s.state.voted_for == Some(s.state.me))
    && t.serial == s.serial && t.pending == s.pending
    && t.state == state::State { role: if ok { state::Role::Candidate } else { s.state.role }, ..s.state }
}

impl WriteVote {
    pub closed spec fn number(&self) -> u64 { self.id }
    pub closed spec fn contents(&self) -> VoteImage { self.image }
    pub fn sequence(&self) -> (r: u64) ensures r == self.number(), { self.id }
    pub fn image(&self) -> (r: VoteImage) ensures r == self.contents(), { self.image }
}

impl Machine {
    pub closed spec fn view(&self) -> OperationView {
        OperationView { state: self.state, serial: self.serial,
            pending: match self.pending { None => None,
                Some(p) => Some((p.id, p.image, p.request, p.reply, p.before@)) } }
    }
    pub proof fn view_is_valid(&self)
        requires self.invariant(),
        ensures view_invariant(self.view()), self.view().state == self.state(),
    {}
    pub closed spec fn state(&self) -> State { self.state }
    pub closed spec fn idle(&self) -> bool { self.pending.is_none() }
    pub closed spec fn invariant(&self) -> bool {
        state::well_formed(self.state) && self.state.last_index == 0 && self.state.last_term == 0
        && match self.pending {
            None => true,
            Some(p) => p.id == self.serial && p.image == image(self.state)
                && state::well_formed(p.before@)
                && state::vote_step(p.before@, p.request, self.state, p.reply),
        }
    }
    pub closed spec fn pending_request(&self) -> Option<VoteRequest> {
        match self.pending { None => None, Some(p) => Some(p.request) }
    }
    pub closed spec fn pending_before(&self) -> State {
        self.pending.unwrap().before@
    }
    pub closed spec fn accepts(&self, op: &WriteVote) -> bool {
        match self.pending { None => false, Some(p) => p.id == op.id && p.image == op.image }
    }

    pub proof fn matching_operation(&self, op: &WriteVote)
        requires self.invariant(), self.accepts(op),
        ensures op.contents() == image(self.state()),
    {}

    pub fn new(me: usize, members: usize) -> (r: Option<Self>)
        ensures r.is_some() == (members > 0 && me < members),
            r.is_some() ==> r.unwrap().invariant() && r.unwrap().idle()
                && state::initial(r.unwrap().state(), me, members)
                && initial_view(r.unwrap().view(), me, members),
    {
        match State::new(me, members) {
            None => None,
            Some(s) => Some(Self { state: s, serial: 0, pending: None }),
        }
    }

    // Version and deployment identity are checked inside verified code.
    pub fn recover(me: usize, members: usize, saved: VoteImage) -> (r: Option<Self>)
        ensures r.is_some() ==> r.unwrap().invariant() && r.unwrap().idle()
            && r.unwrap().state().me == me && r.unwrap().state().members == members
            && r.unwrap().state().term == saved.term
            && r.unwrap().state().voted_for == saved.voted_for
            && image(r.unwrap().state()) == saved
            && r.unwrap().state().role == state::Role::Follower
            && r.unwrap().view().pending.is_none() && r.unwrap().view().serial == 0,
    {
        if saved.version != 1 || saved.me != me || saved.members != members { return None; }
        match State::restore_vote(me, members, saved.term, saved.voted_for) {
            None => None,
            Some(s) => Some(Self { state: s, serial: 0, pending: None }),
        }
    }

    pub fn term(&self) -> (r: u64) ensures r == self.state().term, { self.state.term }
    pub fn is_leader(&self) -> (r: bool)
        ensures r == (self.state().role == state::Role::Leader),
    { self.state.is_leader() }

    pub fn election_request(&self) -> (r: Option<state::VoteRequest>)
        ensures r.is_some() == (self.state().term < u64::MAX),
            r.is_some() ==> r.unwrap().term == self.view().state.term + 1
                && r.unwrap().candidate == self.view().state.me
                && r.unwrap().last_index == self.view().state.last_index
                && r.unwrap().last_term == self.view().state.last_term,
    { self.state.election_request() }

    pub fn campaign(&mut self, term: u64) -> (r: bool)
        requires old(self).invariant(),
        ensures self.invariant(), campaign_step(old(self).view(), term, self.view(), r),
    {
        if self.pending.is_some() { return false; }
        self.state.campaign(term)
    }

    pub fn pending_matches(&self, request: state::VoteRequest) -> (r: bool)
        ensures r == (self.pending_request() == Some(request)),
            r ==> self.view().pending.is_some() && self.view().pending.unwrap().2 == request,
    {
        match self.pending {
            None => false,
            Some(p) => p.request.term == request.term && p.request.candidate == request.candidate
                && p.request.last_index == request.last_index && p.request.last_term == request.last_term,
        }
    }

    pub fn begin_vote(&mut self, request: VoteRequest) -> (op: Option<WriteVote>)
        requires old(self).invariant(),
        ensures self.invariant(),
            op.is_some() ==> self.accepts(&op.unwrap())
                && op.unwrap().contents() == image(self.state())
                && self.pending_request() == Some(request)
                && self.pending_before() == old(self).state(),
            op.is_none() ==> self.state() == old(self).state(),
            begin_step(old(self).view(), request, self.view(),
                match op { None => None, Some(o) => Some((o.number(), o.contents())) }),
    {
        if self.pending.is_some() || self.serial == u64::MAX { return None; }
        let ghost before = self.state;
        let reply = self.state.request_vote(request);
        self.serial = self.serial + 1;
        let saved = VoteImage { version: 1, term: self.state.term,
            voted_for: self.state.voted_for, me: self.state.me, members: self.state.members };
        self.pending = Some(PendingVote { id: self.serial, image: saved,
            request, reply, before: Ghost(before) });
        Some(WriteVote { id: self.serial, image: saved })
    }

    // This is reply authorization, not a claim that arbitrary input is durable.
    // The host caller must supply this operation only after its real write returns.
    pub fn complete_vote(&mut self, completed: WriteVote) -> (reply: Option<VoteReply>)
        requires old(self).invariant(),
        ensures self.invariant(), self.state() == old(self).state(),
            reply.is_some() == old(self).accepts(&completed),
            reply.is_some() ==> self.idle()
                && state::vote_step(old(self).pending_before(),
                    old(self).pending_request().unwrap(), self.state(), reply.unwrap())
                && completed.contents() == image(self.state()),
            complete_step(old(self).view(), completed.number(), completed.contents(), self.view(), reply),
    {
        match self.pending {
            None => None,
            Some(p) => {
                let same = p.id == completed.id
                    && p.image.version == completed.image.version
                    && p.image.term == completed.image.term
                    && p.image.voted_for == completed.image.voted_for
                    && p.image.me == completed.image.me
                    && p.image.members == completed.image.members;
                if !same { return None; }
                self.pending = None;
                Some(p.reply)
            }
        }
    }
}
}
//! Checked storage sequencing. I/O events are supplied only by the real driver.
//! The filesystem effect of each successful host operation is an explicit
//! environment contract in the parent proof, not inferred from a token.
use super::protocol::{self, WriteVote, VoteImage, Machine};
use super::state::VoteReply;
use vstd::prelude::*;
verus! {
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Phase { Create, Write, Sync, Ready, Failed }
#[derive(Clone, Copy, Debug)]
pub enum Action { Create, Write(VoteImage), Sync, Release, Stop }
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Completion { Created, Written, Synced, Failed }

pub struct VoteWrite {
    operation: WriteVote,
    phase: Phase,
}
// No public constructor: only the completed checked flow can produce a receipt.
pub struct WrittenVote { operation: WriteVote }

pub open spec fn next_phase(p: Phase, c: Completion) -> Phase {
    match (p, c) {
        (_, Completion::Failed) => Phase::Failed,
        (Phase::Create, Completion::Created) => Phase::Write,
        (Phase::Write, Completion::Written) => Phase::Sync,
        (Phase::Sync, Completion::Synced) => Phase::Ready,
        _ => Phase::Failed,
    }
}
pub open spec fn action_for(p: Phase, image: VoteImage) -> Action {
    match p {
        Phase::Create => Action::Create,
        Phase::Write => Action::Write(image),
        Phase::Sync => Action::Sync,
        Phase::Ready => Action::Release,
        Phase::Failed => Action::Stop,
    }
}
impl VoteWrite {
    pub closed spec fn phase(&self) -> Phase { self.phase }
    pub closed spec fn id(&self) -> u64 { self.operation.number() }
    pub closed spec fn image(&self) -> VoteImage { self.operation.contents() }
    pub fn new(operation: WriteVote) -> (r: Self)
        ensures r.phase() == Phase::Create, r.id() == operation.number(),
            r.image() == operation.contents(),
    { Self { operation, phase: Phase::Create } }

    pub fn action(&self) -> (r: Action)
        ensures r == action_for(self.phase(), self.image()),
    {
        match self.phase {
            Phase::Create => Action::Create,
            Phase::Write => Action::Write(self.operation.image()),
            Phase::Sync => Action::Sync,
            Phase::Ready => Action::Release,
            Phase::Failed => Action::Stop,
        }
    }
    pub fn complete(&mut self, event: Completion)
        ensures self.id() == old(self).id(), self.image() == old(self).image(),
            self.phase() == next_phase(old(self).phase(), event),
    {
        self.phase = match (self.phase, event) {
            (_, Completion::Failed) => Phase::Failed,
            (Phase::Create, Completion::Created) => Phase::Write,
            (Phase::Write, Completion::Written) => Phase::Sync,
            (Phase::Sync, Completion::Synced) => Phase::Ready,
            _ => Phase::Failed,
        };
    }
    pub fn release(self) -> (r: Option<WrittenVote>)
        ensures r.is_some() == (self.phase() == Phase::Ready),
            r.is_some() ==> r.unwrap().id() == self.id() && r.unwrap().image() == self.image(),
    {
        if matches!(self.phase, Phase::Ready) { Some(WrittenVote { operation: self.operation }) }
        else { None }
    }
}
impl WrittenVote {
    pub closed spec fn id(&self) -> u64 { self.operation.number() }
    pub closed spec fn image(&self) -> VoteImage { self.operation.contents() }
    pub fn matches(&self, id: u64, image: VoteImage) -> (r: bool)
        ensures r == (id == self.id() && image == self.image()),
    {
        let actual = self.operation.image();
        self.operation.sequence() == id && actual.version == image.version
            && actual.term == image.term && actual.voted_for == image.voted_for
            && actual.me == image.me && actual.members == image.members
    }
    pub fn release_reply(self, machine: &mut Machine) -> (r: Option<VoteReply>)
        requires old(machine).invariant(),
        ensures machine.invariant(), machine.state() == old(machine).state(),
            protocol::complete_step(old(machine).view(), self.id(), self.image(), machine.view(), r),
            r.is_some() ==> self.image() == protocol::image(machine.state()),
    { machine.complete_vote(self.operation) }

}
}

